mapper.select:
SELECT p.purchase_id, p.own_name, p.purchase_type, p.total_price, p.address AS delivery_address_id, p.purchase_status, p.create_time,
pd.detail_id, pd.order_id, pd.unin_price, pd.sum_price, pd.count,
o.title, o.price, o.content, o.picture, o.address FROM tb_purchase p LEFT JOIN tb_purchase_detail pd ON p.purchase_id = pd.purchase_id LEFT JOIN tb_order o ON pd.order_id = o.order_id LEFT JOIN tb_address a ON p.address = a.id WHERE p.own_name = #{ownName}
